def cross(o,a,b): return (a[1]-o[1])*(b[0]-o[0])-(a[0]-o[0])*(b[1]-o[1])
P=sorted(pts)
lo=[]
for p in P:
 while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
 lo.append(p)
up=[]
for p in P[::-1]:
 while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
 up.append(p)
hull=lo[:-1]+up[:-1]
print('hull',hull)
# point-in-convex polygon via ray casting; include boundary
def inside(x,y):
 on=False
 for (y1,x1),(y2,x2) in zip(hull,hull[1:]+hull[:1]):
  cr=(x-x1)*(y2-y1)-(y-y1)*(x2-x1)
  if abs(cr)<1e-9 and min(x1,x2)<=x<=max(x1,x2) and min(y1,y2)<=y<=max(y1,y2): return True
  if (y1>y)!=(y2>y) and x < (x2-x1)*(y-y1)/(y2-y1)+x1: on=not on
 return on
